    private static final class Node {
        int value;
        Node prev;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    private final Node sentinel = new Node(0);
    private int size;

    public SentinelIntList() {
        sentinel.next = sentinel;
        sentinel.prev = sentinel;
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public void addFirst(int value) {
        insertBetween(new Node(value), sentinel, sentinel.next);
    }

    public void addLast(int value) {
        insertBetween(new Node(value), sentinel.prev, sentinel);
    }

    public int removeFirst() {
        if (isEmpty()) {
            throw new java.util.NoSuchElementException();
        }
        return unlink(sentinel.next);
    }

    public int removeLast() {
        if (isEmpty()) {
            throw new java.util.NoSuchElementException();
        }
        return unlink(sentinel.prev);
    }

    private void insertBetween(Node node, Node prev, Node next) {
        node.prev = prev;
        node.next = next;
        prev.next = node;
        next.prev = node;
        size++;
    }

    private int unlink(Node node) {
        Node prev = node.prev;
        Node next = node.next;
        prev.next = next;
        next.prev = prev;

        int value = node.value;
        node.prev = null;
        node.next = null;
        size--;
        return value;
    }
}
