        children: "final class LruList<K, V> {
    private final Node<K, V> sentinel = new Node<>(null, null);

    LruList() {
        sentinel.prev = sentinel;
        sentinel.next = sentinel;
    }

    void moveToFront(Node<K, V> node) {
        unlink(node);
        insertAfter(sentinel, node);
    }

    void addFront(Node<K, V> node) {
        insertAfter(sentinel, node);
    }

    Node<K, V> removeLast() {
        if (sentinel.prev == sentinel) {
            return null;
        }
        Node<K, V> lru = sentinel.prev;
        unlink(lru);
        return lru;
    }

    private void insertAfter(Node<K, V> left, Node<K, V> node) {
        Node<K, V> right = left.next;
        node.prev = left;
        node.next = right;
        left.next = node;
        right.prev = node;
    }

    private void unlink(Node<K, V> node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
        node.prev = null;
        node.next = null;
    }

    static final class Node<K, V> {
        final K key;
        V value;
        Node<K, V> prev;
        Node<K, V> next;

